public record Money(long cents) implements Comparable<Money> {
    @Override public int compareTo(Money other) { return Long.compare(cents, other.cents); }
}

public record Version(int major, int minor) implements Comparable<Version> {
    // one method for the whole family; Comparator factories compose the derived orderings
    @Override public int compareTo(Version o) {
        return Comparator.comparingInt(Version::major).thenComparingInt(Version::minor).compare(this, o);
    }
}
